import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Chronology Compendium","description":"","frontmatter":{},"headers":[],"relativePath":"en/93-编年史简表.md","filePath":"en/93-编年史简表.md","lastUpdated":null}'),o={name:"en/93-编年史简表.md"};function d(n,t,s,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="chronology-compendium" tabindex="-1">Chronology Compendium <a class="header-anchor" href="#chronology-compendium" aria-label="Permalink to &quot;Chronology Compendium&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document number</td><td>93</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core keywords</td><td>chronology, era divisions, major events, historical milestones, Hengyuan Universe</td></tr></tbody></table><h2 id="i-notes-on-the-chronology" tabindex="-1">I. Notes on the Chronology <a class="header-anchor" href="#i-notes-on-the-chronology" aria-label="Permalink to &quot;I. Notes on the Chronology&quot;">​</a></h2><p>This compendium records, on the basis of Hengyuan Universe standard time, the major historical events and key milestones in the development of the Anchor Symbiotic Civilization, arranged in chronological order of eras. The time span extends from the ancient period of the Pre-Anchor Era to the future outlook of the Interstellar Symbiosis Era. Each era lists its start and end times, its characteristics, and its major events. This compendium is a highly condensed historical index; for the detailed history of each era, see the dedicated accounts in documents 70–79.</p><h2 id="ii-overview-of-era-divisions" tabindex="-1">II. Overview of Era Divisions <a class="header-anchor" href="#ii-overview-of-era-divisions" aria-label="Permalink to &quot;II. Overview of Era Divisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Era number</th><th>Era name</th><th>Time span (Hengyuan Universe standard years)</th><th>Duration</th><th>Core characteristics</th></tr></thead><tbody><tr><td>First Era</td><td>The Pre-Anchor Era</td><td>approx. −10 billion to −10,000 years</td><td>approx. 10 billion years</td><td>Predatory cultivation systems dominated; civilizations rose and fell in cycles</td></tr><tr><td>Second Era</td><td>The Anchor Awakening Era</td><td>−10,000 to −1,000 years</td><td>approx. 9,000 years</td><td>The anchor mechanism was discovered and initially applied</td></tr><tr><td>Third Era</td><td>The Establishment Period of the Symbiotic System</td><td>−1,000 to −100 years</td><td>approx. 900 years</td><td>The institutional framework of the Anchor Symbiotic Civilization was gradually established</td></tr><tr><td>Fourth Era</td><td>The Opening Period of the Three Hundred Systems</td><td>−100 to −50 years</td><td>approx. 50 years</td><td>The Three Hundred Origin Cultivation Systems were fully opened</td></tr><tr><td>Fifth Era</td><td>The 20% Activation Strategy Period</td><td>−50 years to Year One</td><td>approx. 50 years</td><td>20% of living beings were activated as Supreme Powers of the Plane</td></tr><tr><td>Sixth Era</td><td>The First Ascension Era</td><td>Year One to 100</td><td>100 years</td><td>The symbiotic civilization achieved its first staged ascension</td></tr><tr><td>Seventh Era</td><td>The Republic of Ten Thousand Races Era</td><td>100 to 500</td><td>400 years</td><td>The Republic of Ten Thousand Races was formally established; cross-racial integration deepened</td></tr><tr><td>Eighth Era</td><td>The Cross-Plane Exploration Era</td><td>500 to 2000</td><td>1,500 years</td><td>Large-scale cross-plane exploration and archaeological activities unfolded</td></tr><tr><td>Ninth Era</td><td>The Interstellar Symbiosis Era</td><td>2000 to the future</td><td>ongoing</td><td>A universe-level symbiosis network was completed; overall ascension advanced</td></tr></tbody></table><p>Note: &quot;Year One&quot; refers to the year in which the Anchor Symbiotic Civilization was formally proclaimed, serving as the dividing point of this historical calendar.</p><h2 id="iii-the-pre-anchor-era-approx-−10-billion-to-−10-000-years" tabindex="-1">III. The Pre-Anchor Era (approx. −10 billion to −10,000 years) <a class="header-anchor" href="#iii-the-pre-anchor-era-approx-−10-billion-to-−10-000-years" aria-label="Permalink to &quot;III. The Pre-Anchor Era (approx. −10 billion to −10,000 years)&quot;">​</a></h2><p>The Pre-Anchor Era was the longest era in the history of the Hengyuan Universe, lasting approximately ten billion years. Its core characteristic was that predatory cultivation systems dominated the universe, with civilizations repeatedly cycling through &quot;rise—zenith—predation—collapse.&quot;</p><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>approx. −10 billion years</td><td>The law network of the Hengyuan Universe stabilized; the first material planes formed; the universe entered a habitable state</td></tr><tr><td>approx. −8 billion years</td><td>The first intelligent life emerged on multiple material planes; primitive cultivation systems began to sprout</td></tr><tr><td>approx. −5 billion years</td><td>Predatory cultivation systems gradually became mainstream; the strong achieved rapid evolution by devouring the weak</td></tr><tr><td>approx. −3 billion years</td><td>The first universe-scale predation war erupted; civilizations in multiple star regions suffered devastating blows</td></tr><tr><td>approx. −1 billion years</td><td>The drawbacks of the predatory system began to manifest; the overall entropy increase of the universe accelerated; cultivation resources gradually dried up</td></tr><tr><td>approx. −500 million years</td><td>The first thinkers reflecting on the predatory system appeared; the sprouts of symbiotic thought began to take shape</td></tr><tr><td>approx. −100 million years</td><td>Small-scale experimental symbiotic civilizations emerged in multiple star regions, but all were destroyed by predatory civilizations</td></tr><tr><td>approx. −1 million years</td><td>The universe as a whole entered the &quot;Great Decline&quot;; both the number of civilizations and the level of cultivation fell to historical lows</td></tr><tr><td>approx. −10,000 years</td><td>A cultivator on the First Plane, during long-term cultivation, accidentally perceived a stable node in the law network; the anchor mechanism was discovered for the first time</td></tr></tbody></table><h2 id="iv-the-anchor-awakening-era-−10-000-to-−1-000-years" tabindex="-1">IV. The Anchor Awakening Era (−10,000 to −1,000 years) <a class="header-anchor" href="#iv-the-anchor-awakening-era-−10-000-to-−1-000-years" aria-label="Permalink to &quot;IV. The Anchor Awakening Era (−10,000 to −1,000 years)&quot;">​</a></h2><p>The Anchor Awakening Era was the transitional period of the anchor mechanism from discovery to initial application. Its core characteristic was the gradual maturation of anchor technology and the spread of symbiotic thought.</p><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>−10,000 years</td><td>The anchor mechanism was discovered for the first time; the discoverer named it the &quot;Anchor&quot; and began systematic research</td></tr><tr><td>−9,000 years</td><td>The first artificial anchor was successfully established, proving that anchors could be artificially constructed and maintained</td></tr><tr><td>−8,000 years</td><td>Anchor technology began to spread within a small scope; the first anchor cultivators appeared</td></tr><tr><td>−7,000 years</td><td>It was discovered that anchors could serve as benchmarks for cross-plane connections; the first recorded anchor-assisted plane traversal succeeded</td></tr><tr><td>−6,000 years</td><td>Symbiotic thought began to combine with anchor technology; the first theoretical texts on &quot;Anchor Symbiosis&quot; were published</td></tr><tr><td>−5,000 years</td><td>The first symbiotic city-state based on anchors was established, proving the feasibility of the symbiotic system</td></tr><tr><td>−4,000 years</td><td>Predatory civilizations launched attacks on symbiotic city-states; the symbiotic city-states successfully defended themselves by virtue of anchor technology</td></tr><tr><td>−3,000 years</td><td>Symbiotic thought spread across multiple star regions; more and more civilizations began to attempt the symbiotic transition</td></tr><tr><td>−2,000 years</td><td>The first &quot;Great Symbiosis Assembly of the Ten Thousand Races&quot; convened; representatives from dozens of races jointly discussed the future of symbiotic civilization</td></tr><tr><td>−1,000 years</td><td>Anchor technology and symbiotic thought had acquired the conditions for establishing a unified civilization; the Establishment Period of the Symbiotic System began</td></tr></tbody></table><h2 id="v-the-establishment-period-of-the-symbiotic-system-−1-000-to-−100-years" tabindex="-1">V. The Establishment Period of the Symbiotic System (−1,000 to −100 years) <a class="header-anchor" href="#v-the-establishment-period-of-the-symbiotic-system-−1-000-to-−100-years" aria-label="Permalink to &quot;V. The Establishment Period of the Symbiotic System (−1,000 to −100 years)&quot;">​</a></h2><p>The Establishment Period of the Symbiotic System was the crucial period in which the institutional framework of the Anchor Symbiotic Civilization grew from nothing.</p><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>−1,000 years</td><td>The Symbiotic Constitution Drafting Committee was established and began drafting the fundamental law</td></tr><tr><td>−950 years</td><td>The draft of the Symbiotic Constitution was completed; opinions were widely solicited from all races</td></tr><tr><td>−900 years</td><td>The Symbiotic Constitution was passed by a universal referendum and took effect; the Anchor Symbiotic Civilization was proclaimed</td></tr><tr><td>−850 years</td><td>The three major institutions — the Anchor Assembly, the Symbiotic Executive Committee, and the Symbiotic Court — were formally established and operational</td></tr><tr><td>−800 years</td><td>The Output-Linked Contract Mechanism began to be promoted across the entire domain</td></tr><tr><td>−700 years</td><td>Basic laws such as the Symbiotic Labor Law and the Consumer Protection Law were promulgated one after another</td></tr><tr><td>−600 years</td><td>The five supporting laws on education, medical care, housing, environment, and antitrust were all promulgated and implemented</td></tr><tr><td>−500 years</td><td>The excavation and compilation of the Three Hundred Origin Cultivation Systems was officially launched</td></tr><tr><td>−400 years</td><td>The first fifty Origin Cultivation Systems completed compilation and verification</td></tr><tr><td>−300 years</td><td>Breakthroughs were made in the technological application of the Multiplying Fruit; the hundredfold deduction amplification technology matured</td></tr><tr><td>−200 years</td><td>All Three Hundred Systems completed compilation and entered the final safety verification stage</td></tr><tr><td>−100 years</td><td>The conditions for the full opening of the Three Hundred Origin Cultivation Systems matured; the opening period began</td></tr></tbody></table><h2 id="vi-the-opening-period-of-the-three-hundred-systems-−100-to-−50-years" tabindex="-1">VI. The Opening Period of the Three Hundred Systems (−100 to −50 years) <a class="header-anchor" href="#vi-the-opening-period-of-the-three-hundred-systems-−100-to-−50-years" aria-label="Permalink to &quot;VI. The Opening Period of the Three Hundred Systems (−100 to −50 years)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>−100 years</td><td>The Three Hundred Origin Cultivation Systems were formally opened free of charge to all living beings of the universe</td></tr><tr><td>−90 years</td><td>The number of cultivators increased a hundredfold within ten years; &quot;a path for everyone&quot; was preliminarily realized</td></tr><tr><td>−80 years</td><td>The Three Origin Foundations (Deduction Iteration, Life Cycle, and Spatial Legal Principle Dispatch) became the most popular systems</td></tr><tr><td>−70 years</td><td>The first cultivators who reached high positions through the new systems appeared, proving the effectiveness of the systems</td></tr><tr><td>−60 years</td><td>The mentor network was comprehensively established; advanced cultivators began to fulfill their statutory duty of guiding beginner cultivators</td></tr><tr><td>−50 years</td><td>The overall cultivation level of the entire population rose substantially; the conditions for the 20% Activation Strategy matured</td></tr></tbody></table><h2 id="vii-the-20-activation-strategy-period-−50-years-to-year-one" tabindex="-1">VII. The 20% Activation Strategy Period (−50 years to Year One) <a class="header-anchor" href="#vii-the-20-activation-strategy-period-−50-years-to-year-one" aria-label="Permalink to &quot;VII. The 20% Activation Strategy Period (−50 years to Year One)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>−50 years</td><td>The 20% Activation Strategy was officially launched, aiming to activate 20% of living beings as Supreme Powers of the Plane within 50 years</td></tr><tr><td>−40 years</td><td>The first Supreme Powers of the Plane were born; the activation rate reached 5%</td></tr><tr><td>−30 years</td><td>The activation rate reached 10%; Supreme Powers of the Plane began to play a core role in anchor maintenance</td></tr><tr><td>−20 years</td><td>The activation rate reached 15%; the overall cultivation level of the universe achieved a qualitative leap</td></tr><tr><td>−10 years</td><td>The activation rate reached 18%, approaching the strategic target</td></tr><tr><td>Year One</td><td>The activation rate reached 20.3%; the 20% Activation Strategy was completed with full success, and the Anchor Symbiotic Civilization entered a new era</td></tr></tbody></table><h2 id="viii-the-first-ascension-era-year-one-to-100" tabindex="-1">VIII. The First Ascension Era (Year One to 100) <a class="header-anchor" href="#viii-the-first-ascension-era-year-one-to-100" aria-label="Permalink to &quot;VIII. The First Ascension Era (Year One to 100)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>Year One</td><td>The symbiotic civilization formally proclaimed its entry into the Ascension Era; the first stage of the Four-Stage Ascension Path (Founding Reality) was completed</td></tr><tr><td>20</td><td>The second stage (Technological Empowerment) advanced comprehensively; cultivation laws and technological engineering became deeply integrated</td></tr><tr><td>40</td><td>Replication Mirror technology and isolated space technology achieved engineering-level mass production; cross-plane archaeology entered the era of scale</td></tr><tr><td>60</td><td>The first consciousness-ascension cultivators reached high ranks; the third stage (Consciousness Evolution) began</td></tr><tr><td>80</td><td>The infrastructure construction of the consciousness domain was completed; consciousness migration technology preliminarily matured</td></tr><tr><td>100</td><td>The first staged ascension succeeded; the symbiotic civilization as a whole was elevated by half a dimension level</td></tr></tbody></table><h2 id="ix-the-republic-of-ten-thousand-races-era-100-to-500" tabindex="-1">IX. The Republic of Ten Thousand Races Era (100 to 500) <a class="header-anchor" href="#ix-the-republic-of-ten-thousand-races-era-100-to-500" aria-label="Permalink to &quot;IX. The Republic of Ten Thousand Races Era (100 to 500)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>100</td><td>The Republic of Ten Thousand Races was formally proclaimed; all intelligent races achieved equal union within the framework of the symbiotic civilization</td></tr><tr><td>150</td><td>The Register of Ten Thousand Races completed compilation, recording all known intelligent races</td></tr><tr><td>200</td><td>Cross-racial intermarriage and cultural fusion became the norm; new mixed races began to emerge</td></tr><tr><td>300</td><td>The promotion of a common language for all races was completed; barriers to cross-racial communication were basically eliminated</td></tr><tr><td>400</td><td>The cultures of the Ten Thousand Races flourished; the traditional cultures of each race were protected and developed within the symbiotic framework</td></tr><tr><td>500</td><td>The Republic of Ten Thousand Races entered its mature period; the conditions for cross-plane exploration became fully mature</td></tr></tbody></table><h2 id="x-the-cross-plane-exploration-era-500-to-2000" tabindex="-1">X. The Cross-Plane Exploration Era (500 to 2000) <a class="header-anchor" href="#x-the-cross-plane-exploration-era-500-to-2000" aria-label="Permalink to &quot;X. The Cross-Plane Exploration Era (500 to 2000)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>500</td><td>The large-scale cross-plane exploration program was officially launched; the Plane Administration was established</td></tr><tr><td>600</td><td>More than a thousand planes were explored; the master database of plane coordinates was preliminarily completed</td></tr><tr><td>800</td><td>The Replication Mirror remote-site archaeology scheme became fully mature; cross-plane archaeology entered its golden age</td></tr><tr><td>1000</td><td>Breakthroughs were made in time regression technology; the principle of observe first, then intervene within limits was formally established</td></tr><tr><td>1200</td><td>More than one hundred thousand planes were explored; diplomatic relations were established with dozens of plane civilizations</td></tr><tr><td>1500</td><td>The cross-plane ethics guidelines were comprehensively implemented; interaction among civilizations entered the era of regulation</td></tr><tr><td>1800</td><td>The time paradox prevention and control mechanism fully matured; time regression archaeology achieved scale</td></tr><tr><td>2000</td><td>Cross-plane exploration achieved splendid results; the conditions for the Interstellar Symbiosis Era became fully mature</td></tr></tbody></table><h2 id="xi-the-interstellar-symbiosis-era-2000-to-the-future" tabindex="-1">XI. The Interstellar Symbiosis Era (2000 to the future) <a class="header-anchor" href="#xi-the-interstellar-symbiosis-era-2000-to-the-future" aria-label="Permalink to &quot;XI. The Interstellar Symbiosis Era (2000 to the future)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time node</th><th>Major event</th></tr></thead><tbody><tr><td>2000</td><td>The Interstellar Symbiosis Era formally began; the fourth stage (Interstellar Symbiosis) advanced comprehensively</td></tr><tr><td>2500 (outlook)</td><td>The universe-level anchor network was preliminarily completed, covering all explored planes</td></tr><tr><td>3000 (outlook)</td><td>The cross-plane symbiosis system matured; the Ten Thousand Races achieved true symbiosis across the universe</td></tr><tr><td>5000 (outlook)</td><td>The overall ascension of the universe was completed; the Hengyuan Universe entered a state of existence at a higher dimension</td></tr><tr><td>The future (outlook)</td><td>The Anchor Symbiotic Civilization continued to explore beyond the universe, spreading the ideal of symbiosis to broader realms of existence</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Chronology Compendium is the epic of struggle of the Anchor Symbiotic Civilization — from ignorance to awakening, from weakness to strength, from its own plane to the entire universe. The succession of each era bears witness to symbiotic ideals triumphing over predatory ideals, and civilized progress triumphing over barbaric decline. History is not the dust of the past but the seed of the future — to understand this history is to understand whence the symbiotic civilization came and whither it goes.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>70-纪元划分总表 (Chronology of Eras — Master Table)</li><li>72-锚点觉醒纪元 (The Anchor Awakening Era)</li><li>79-星际共生时代展望 (The Outlook of the Interstellar Symbiosis Era)</li></ul>',32)])])}const y=e(o,[["render",d]]);export{u as __pageData,y as default};
